"use strict";

function objectSpread(target) {
    for (let i = 1; i < arguments.length; i++) {
        const source = arguments[i] === null ? {} : arguments[i];
        const keys = Object.keys(source);
        
        if (typeof Object.getOwnPropertySymbols === 'function') {
            keys.push(
                ...Object.getOwnPropertySymbols(source)
                    .filter(sym => Object.getOwnPropertyDescriptor(source, sym).enumerable)
            );
        }
        
        keys.forEach(key => {
            defineProperty(target, key, source[key]);
        });
    }
    return target;
}

function defineProperty(obj, key, value) {
    if (key in obj) {
        Object.defineProperty(obj, key, {
            value,
            enumerable: true,
            configurable: true,
            writable: true
        });
    } else {
        obj[key] = value;
    }
    return obj;
}

class MetingJSElement extends HTMLElement {
    constructor() {
        super();
        this._initState = {
            isScrolling: false,
            scrollTimer: null,
            preventScrollTimer: null,
            lastScrollTop: 0,
            autoScrollTimeout: 5000,
            touchStartY: 0,
            touchStartX: 0,
            lastTouchY: 0,
            isTouchMove: false,
            scrollVelocity: 0,
            isInertialScrolling: false,
            touchStartTime: 0,
            preventAutoScroll: false,
            lastManualScrollPosition: 0,
            manualScrolling: false
        };
    }

    connectedCallback() {
        if (window.APlayer && window.fetch) {
            this.init();
            this._parse();
        }
    }

    disconnectedCallback() {
        if (!this.lock) {
            this.aplayer?.destroy();
        }
        this._removeScrollListeners();
        this._cleanup?.();
    }

    _removeScrollListeners() {
        const lrcContainer = this.querySelector('.aplayer-lrc');
        if (lrcContainer) {
            lrcContainer.removeEventListener('wheel', this._handleWheel);
            lrcContainer.removeEventListener('touchstart', this._handleTouchStart);
            lrcContainer.removeEventListener('touchmove', this._handleTouchMove);
            lrcContainer.removeEventListener('touchend', this._handleTouchEnd);
        }
        clearTimeout(this._initState.scrollTimer);
        clearTimeout(this._initState.preventScrollTimer);
        this._initState.isInertialScrolling = false;
    }

    _camelize(str) {
        return str
            .replace(/^[_.\- ]+/, '')
            .toLowerCase()
            .replace(/[_.\- ]+(\w|$)/g, (_, c) => c.toUpperCase());
    }

    init() {
        const attrs = {};
        for (let i = 0; i < this.attributes.length; i++) {
            attrs[this._camelize(this.attributes[i].name)] = this.attributes[i].value;
        }

        const metaKeys = [
            'server', 'type', 'id', 'api', 'auth', 'auto', 'lock',
            'name', 'title', 'artist', 'author', 'url', 'cover',
            'pic', 'lyric', 'lrc', 'noLyricText'
        ];

        this.meta = {};
        metaKeys.forEach(key => {
            this.meta[key] = attrs[key];
            delete attrs[key];
        });

        this.meta.noLyricText = this.meta.noLyricText || '暂无歌词';
        this.config = attrs;
        this.api = this.meta.api || 
                   window.meting_api || 
                   'https://api.i-meto.com/meting/api?server=:server&type=:type&id=:id&r=:r';

        if (this.meta.auto) {
            this._parse_link();
        }
    }

    _parse_link() {
        const patterns = [
            ['music.163.com.*song.*id=(\\d+)', 'netease', 'song'],
            ['music.163.com.*album.*id=(\\d+)', 'netease', 'album'],
            ['music.163.com.*artist.*id=(\\d+)', 'netease', 'artist'],
            ['music.163.com.*playlist.*id=(\\d+)', 'netease', 'playlist'],
            ['music.163.com.*discover/toplist.*id=(\\d+)', 'netease', 'playlist'],
            ['y.qq.com.*song/(\\w+).html', 'tencent', 'song'],
            ['y.qq.com.*album/(\\w+).html', 'tencent', 'album'],
            ['y.qq.com.*singer/(\\w+).html', 'tencent', 'artist'],
            ['y.qq.com.*playsquare/(\\w+).html', 'tencent', 'playlist'],
            ['y.qq.com.*playlist/(\\w+).html', 'tencent', 'playlist'],
            ['xiami.com.*song/(\\w+)', 'xiami', 'song'],
            ['xiami.com.*album/(\\w+)', 'xiami', 'album'],
            ['xiami.com.*artist/(\\w+)', 'xiami', 'artist'],
            ['xiami.com.*collect/(\\w+)', 'xiami', 'playlist']
        ];

        for (const [pattern, server, type] of patterns) {
            const regex = new RegExp(pattern);
            const match = regex.exec(this.meta.auto);
            
            if (match !== null) {
                this.meta.server = server;
                this.meta.type = type;
                this.meta.id = match[1];
                return;
            }
        }
    }

    _parse() {
        if (this.meta.url) {
            const audioData = {
                name: this.meta.name || this.meta.title || '音频名称',
                artist: this.meta.artist || this.meta.author || '艺术家',
                url: this.meta.url,
                cover: this.meta.cover || this.meta.pic,
                lrc: this.meta.lrc || this.meta.lyric || '',
                type: this.meta.type || 'auto'
            };

            if (!audioData.lrc) {
                audioData.lrc = `[00:00.00]${this.meta.noLyricText}`;
                this.meta.lrcType = 1;
            } else if (this.innerText) {
                audioData.lrc = this.innerText;
                this.meta.lrcType = 2;
            }

            this._loadPlayer([audioData]);
            return;
        }

        const apiUrl = this.api
            .replace(':server', this.meta.server)
            .replace(':type', this.meta.type)
            .replace(':id', this.meta.id)
            .replace(':auth', this.meta.auth)
            .replace(':r', Math.random());

        fetch(apiUrl)
            .then(response => response.json())
            .then(data => {
                if (Array.isArray(data)) {
                    data.forEach(item => {
                        if (!item.lrc) {
                            item.lrc = `[00:00.00]${this.meta.noLyricText}`;
                        }
                    });
                }
                this._loadPlayer(data);
            })
            .catch(e => {
                this._loadPlayer([{
                    name: '加载失败',
                    artist: '未知错误',
                    url: '',
                    cover: '',
                    lrc: `[00:00.00]加载失败：${e.message}`,
                    type: 'auto'
                }]);
            });
    }

    _loadPlayer(audio) {
        const defaultConfig = {
            audio,
            mutex: true,
            lrcType: this.meta.lrcType || 3,
            storageName: 'metingjs',
            noLyricText: this.meta.noLyricText
        };

        if (audio.length) {
            const config = objectSpread({}, defaultConfig, this.config);
            
            Object.keys(config).forEach(key => {
                if (config[key] === 'true' || config[key] === 'false') {
                    config[key] = config[key] === 'true';
                }
            });

            const container = document.createElement('div');
            config.container = container;
            this.appendChild(container);
            this.aplayer = new APlayer(config);

            this._initLyricFeatures();

            this.aplayer.on('error', () => {
                console.warn('音频加载失败，请检查音源是否可用');
            });

            this.aplayer.on('timeupdate', () => {
                if (this._initState.isScrolling || this._initState.isTouchMove || this._initState.preventAutoScroll) {
                    const lrcContent = this.querySelector('.aplayer-lrc-contents');
                    if (lrcContent) {
                        lrcContent.style.transition = 'none';
                        if (this._initState.manualScrolling) {
                            const currentTransform = getComputedStyle(lrcContent).transform;
                            const matrix = new DOMMatrix(currentTransform);
                            this._initState.lastManualScrollPosition = matrix.m42;
                        }
                    }
                    return;
                }
            });

            // 初始化基础样式
            if (!document.getElementById('meting-style')) {
                const style = document.createElement('style');
                style.id = 'meting-style';
                style.textContent = `
                    .aplayer-lrc-contents p {
                        cursor: pointer !important;
                        transition: color 0.3s ease-in-out, background-color 0.3s ease-in-out;
                        padding: 2px 4px;
                        margin: 2px 0;
                        border-radius: 4px;
                        -webkit-tap-highlight-color: transparent;
                        position: relative;
                        z-index: 1;
                    }
                    .aplayer-lrc-contents p:hover {
                        color: #fff !important;
                        background-color: rgba(255, 255, 255, 0.1);
                    }
                    .aplayer-lrc {
                        user-select: none;
                        -webkit-user-select: none;
                        pointer-events: auto !important;
                    }
                    .aplayer-lrc-current {
                        color: #fff !important;
                        font-weight: bold;
                    }
                `;
                document.head.appendChild(style);
            }
        }
    }

    _initLyricFeatures() {
        // 检查是否应该禁用交互
        const shouldDisableInteraction = () => {
            return window.innerWidth <= 768 && 
                   this.querySelector('.aplayer')?.classList.contains('aplayer-list-show') &&
                   !event.target.closest('.aplayer-icon-menu');
        };

        // 处理禁用交互时的UI更新
        const handleDisabledInteraction = () => {
            const container = this.querySelector('.aplayer');
            const playlist = this.querySelector('.aplayer-list');
            if (playlist) {
                playlist.classList.add('aplayer-list-hide');
                container.classList.remove('aplayer-list-show');
            }
            return true;
        };

        // 处理滚动状态
        this._handleScroll = (lrcContent, newY) => {
            if (!lrcContent) return;

            clearTimeout(this._initState.scrollTimer);
            clearTimeout(this._initState.preventScrollTimer);
            
            this._initState.isScrolling = true;
            this._initState.preventAutoScroll = true;
            this._initState.manualScrolling = true;
            
            lrcContent.style.transition = 'none';
            lrcContent.style.transform = `translateY(${newY}px)`;
            
            this._initState.preventScrollTimer = setTimeout(() => {
                this._initState.preventAutoScroll = false;
                this._initState.isScrolling = false;
                this._initState.manualScrolling = false;
                
                if (!this._initState.isTouchMove) {
                    lrcContent.style.transition = 'transform 0.5s ease-out';
                }
            }, this._initState.autoScrollTimeout);
        };

        // 处理鼠标滚轮事件
        this._handleWheel = (e) => {
            if (shouldDisableInteraction()) {
                e.preventDefault();
                return;
            }

            e.preventDefault();
            const lrcContent = this.querySelector('.aplayer-lrc-contents');
            if (!lrcContent) return;
            
            const currentTransform = getComputedStyle(lrcContent).transform;
            const matrix = new DOMMatrix(currentTransform);
            let newY = matrix.m42 - e.deltaY;
            
            newY = Math.min(0, newY);
            
            this._handleScroll(lrcContent, newY);
        };

        // 触摸事件处理
this._handleTouchStart = (e) => {
    // 如果页面小于768px且列表显示时，禁用除菜单按钮外的所有交互
    if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
        if (!e.target.closest('.aplayer-icon-menu')) {
            e.preventDefault();
            return;
        }
    }
    
    this._initState.isInertialScrolling = false;
    this._initState.touchStartY = e.touches[0].clientY;
    this._initState.touchStartX = e.touches[0].clientX;
    this._initState.lastTouchY = e.touches[0].clientY;
    this._initState.touchStartTime = Date.now();
    this._initState.isTouchMove = false;
    this._initState.manualScrolling = true;

    const lrcContent = this.querySelector('.aplayer-lrc-contents');
    if (lrcContent) {
        lrcContent.style.transition = 'none';
    }

    clearTimeout(this._initState.scrollTimer);
    clearTimeout(this._initState.preventScrollTimer);
};

this._handleTouchMove = (e) => {
    // 如果页面小于768px且列表显示时，禁用滚动
    if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
        e.preventDefault();
        return;
    }

    if (!e.touches[0]) return;

    const moveX = Math.abs(e.touches[0].clientX - this._initState.touchStartX);
    const moveY = Math.abs(e.touches[0].clientY - this._initState.touchStartY);
    
    if (moveY > moveX && e.cancelable) {
        e.preventDefault();
        e.stopPropagation();
    }
    
    if (moveX > 10 || moveY > 10) {
        this._initState.isTouchMove = true;
    }

    if (this._initState.isTouchMove && moveY > moveX) {
        const lrcContent = this.querySelector('.aplayer-lrc-contents');
        if (!lrcContent) return;
        
        const currentY = e.touches[0].clientY;
        const deltaY = currentY - this._initState.lastTouchY;
        this._initState.lastTouchY = currentY;
        
        const currentTransform = getComputedStyle(lrcContent).transform;
        const matrix = new DOMMatrix(currentTransform);
        let newY = matrix.m42 + deltaY;
        
        newY = Math.min(0, newY);
        
        this._handleScroll(lrcContent, newY);
        this._initState.scrollVelocity = deltaY;
    }
};

this._handleTouchEnd = (e) => {
    // 如果页面小于768px且列表显示时，禁用所有交互除了菜单按钮
    if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
        if (!e.target.closest('.aplayer-icon-menu')) {
            const container = this.querySelector('.aplayer');
            const playlist = this.querySelector('.aplayer-list');
            if (playlist) {
                playlist.classList.add('aplayer-list-hide');
                container.classList.remove('aplayer-list-show');
            }
            return;
        }
    }

    const touchEndTime = Date.now();
    const touchDuration = touchEndTime - this._initState.touchStartTime;
    
    const touchEndY = e.changedTouches[0].clientY;
    const touchEndX = e.changedTouches[0].clientX;
    
    const moveY = Math.abs(touchEndY - this._initState.touchStartY);
    const moveX = Math.abs(touchEndX - this._initState.touchStartX);
    
    // 如果页面小于768px且列表显示时，禁用点击事件
    if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
        return;
    }

    if (!this._initState.isTouchMove && touchDuration < 300 && moveY < 10 && moveX < 10) {
        this._lrcClickHandler(e);
        this._initState.preventAutoScroll = false;
        this._initState.manualScrolling = false;
        return;
    }

    const lrcContent = this.querySelector('.aplayer-lrc-contents');
    if (!lrcContent) return;

    lrcContent.style.transition = 'transform 0.3s ease-out';
    
    const currentTransform = getComputedStyle(lrcContent).transform;
    const matrix = new DOMMatrix(currentTransform);
    const currentY = matrix.m42;
    
    if (currentY > 0) {
        lrcContent.style.transform = 'translateY(0)';
        this._initState.preventAutoScroll = false;
        this._initState.manualScrolling = false;
    } else if (Math.abs(this._initState.scrollVelocity) > 2) {
        this._initState.isInertialScrolling = true;
        lrcContent.style.transition = 'none';
        this._inertialScroll();
    }
};

// 惯性滚动
this._inertialScroll = () => {
    if (!this._initState.isInertialScrolling) return;
    
    this._initState.scrollVelocity *= 0.95;
    
    if (Math.abs(this._initState.scrollVelocity) > 0.5) {
        const lrcContent = this.querySelector('.aplayer-lrc-contents');
        if (lrcContent) {
            const currentTransform = getComputedStyle(lrcContent).transform;
            const matrix = new DOMMatrix(currentTransform);
            let newY = matrix.m42 + this._initState.scrollVelocity;
            
            newY = Math.min(0, newY);
            
            lrcContent.style.transform = `translateY(${newY}px)`;
            requestAnimationFrame(() => this._inertialScroll());
        }
    } else {
        this._initState.isInertialScrolling = false;
    }
};

// 歌词点击处理
this._lrcClickHandler = (e) => {
    if (!this.aplayer || !e.target) return;

    // 如果页面小于768px且列表显示时，点击任意区域隐藏列表并禁用歌词点击
    if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
        if (!e.target.closest('.aplayer-icon-menu')) {
            const container = this.querySelector('.aplayer');
            const playlist = this.querySelector('.aplayer-list');
            if (playlist) {
                playlist.classList.add('aplayer-list-hide');
                container.classList.remove('aplayer-list-show');
            }
            return;
        }
    }
    
    // 页面小于768px时，点击歌词不显示列表
    if (window.innerWidth <= 768) {
        const container = this.querySelector('.aplayer');
        const playlist = this.querySelector('.aplayer-list');
        if (playlist && !playlist.classList.contains('aplayer-list-hide')) {
            playlist.classList.add('aplayer-list-hide');
            container.classList.remove('aplayer-list-show');
        }
    }

    if (e.target.closest('.aplayer-control')) return;

    const line = e.target.closest('.aplayer-lrc-contents p');
    if (!line) return;

    const lines = Array.from(this.querySelector('.aplayer-lrc-contents').children);
    const index = lines.indexOf(line);

    if (this.aplayer.lrc && 
        this.aplayer.lrc.parsed && 
        this.aplayer.lrc.parsed[this.aplayer.list.index] && 
        this.aplayer.lrc.parsed[this.aplayer.list.index][index]) {
        
        const time = this.aplayer.lrc.parsed[this.aplayer.list.index][index][0];
        this.aplayer.seek(time);

        if (this.aplayer.paused) {
            this.aplayer.play();
        }

        clearTimeout(this._initState.preventScrollTimer);
        clearTimeout(this._initState.scrollTimer);
        this._initState.preventAutoScroll = false;
        this._initState.isScrolling = false;
        this._initState.isTouchMove = false;
        this._initState.manualScrolling = false;

        const lrcContent = this.querySelector('.aplayer-lrc-contents');
        if (lrcContent) {
            lrcContent.style.transition = 'transform 0.3s ease-out';
            lrcContent.style.transform = 'translateY(0)';
        }
    }
};

// 绑定事件
const bindEvents = () => {
    const lrcContainer = this.querySelector('.aplayer-lrc');
    const container = this.querySelector('.aplayer');
    
    if (!lrcContainer || !container) {
        setTimeout(bindEvents, 100);
        return;
    }
    
    container.addEventListener('contextmenu', (e) => {
        e.preventDefault();
    });

    lrcContainer.addEventListener('contextmenu', (e) => {
        e.preventDefault();
    });

    // 移除旧的事件监听器
    lrcContainer.removeEventListener('wheel', this._handleWheel);
    lrcContainer.removeEventListener('click', this._lrcClickHandler);
    lrcContainer.removeEventListener('touchstart', this._handleTouchStart);
    lrcContainer.removeEventListener('touchmove', this._handleTouchMove);
    lrcContainer.removeEventListener('touchend', this._handleTouchEnd);

    // 添加事件监听器
    lrcContainer.addEventListener('wheel', (e) => {
        // 如果页面小于768px且列表显示时，禁用滚动
        if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
            e.preventDefault();
            return;
        }
        this._handleWheel(e);
    }, { passive: false });
    
    lrcContainer.addEventListener('click', (e) => {
        // 如果页面小于768px且列表显示时，禁用点击
        if (window.innerWidth <= 768 && this.querySelector('.aplayer').classList.contains('aplayer-list-show')) {
            if (!e.target.closest('.aplayer-icon-menu')) {
                const container = this.querySelector('.aplayer');
                const playlist = this.querySelector('.aplayer-list');
                if (playlist) {
                    playlist.classList.add('aplayer-list-hide');
                    container.classList.remove('aplayer-list-show');
                }
                return;
            }
        }
        this._lrcClickHandler(e);
    });
    
    // 为所有歌词行添加点击样式
    const lrcLines = lrcContainer.querySelectorAll('.aplayer-lrc-contents p');
    lrcLines.forEach(line => {
        line.style.cursor = 'pointer';
        line.addEventListener('click', (e) => {
            e.stopPropagation();
            this._lrcClickHandler(e);
        });
    });

    // 触摸设备事件监听器
    if ('ontouchstart' in window) {
        lrcContainer.addEventListener('touchstart', this._handleTouchStart, { passive: false });
        lrcContainer.addEventListener('touchmove', this._handleTouchMove, { passive: false });
        lrcContainer.addEventListener('touchend', this._handleTouchEnd);
    }

    // 菜单按钮处理
    const menuButton = this.querySelector('.aplayer-icon-menu');
    if (menuButton) {
        const clonedButton = menuButton.cloneNode(true);
        menuButton.parentNode.replaceChild(clonedButton, menuButton);
        
        clonedButton.addEventListener('click', (e) => {
            e.stopPropagation();
            const playlist = this.querySelector('.aplayer-list');
            if (playlist) {
                playlist.classList.toggle('aplayer-list-hide');
                container.classList.toggle('aplayer-list-show');
            }
        });
    }
};

// 初始化必要的样式
if (!document.getElementById('meting-style')) {
    const style = document.createElement('style');
    style.id = 'meting-style';
    style.textContent = `
        .aplayer-lrc-contents p {
            cursor: pointer !important;
            transition: color 0.3s ease-in-out, background-color 0.3s ease-in-out;
            padding: 2px 4px;
            margin: 2px 0;
            border-radius: 4px;
            -webkit-tap-highlight-color: transparent;
            position: relative;
            z-index: 1;
        }
        .aplayer-lrc-contents p:hover {
            color: #fff !important;
            background-color: rgba(255, 255, 255, 0.1);
        }
        .aplayer-lrc {
            user-select: none;
            -webkit-user-select: none;
            pointer-events: auto !important;
        }
        .aplayer-lrc-current {
            color: #fff !important;
            font-weight: bold;
        }
    `;
    document.head.appendChild(style);
}

// 初始化绑定事件
bindEvents();

// 绑定resize事件
window.addEventListener('resize', this._resizeHandler);
    }
}

// 注册自定义元素
if (window.customElements && !window.customElements.get('meting-js')) {
    window.MetingJSElement = MetingJSElement;
    window.customElements.define('meting-js', MetingJSElement);
}